00170     private function callWin32Service($function, $param, $checkError = false): mixed
00171     {
00172         $result = false;
00173         if ( function_exists( $function ) ) {
00174             if (!isset(self::$loggedFunctions[$function])) {
00175                 Log::trace('Win32 function: ' . $function . ' exists');
00176                 self::$loggedFunctions[$function] = true;
00177             }
00178 
00179             // Special handling for win32_query_service_status to prevent hanging
00180             if ($function === 'win32_query_service_status') {
00181                 Log::trace("Using enhanced handling for win32_query_service_status");
00182 
00183                 // Set a shorter timeout for this specific function
00184                 $originalTimeout = ini_get('max_execution_time');
00185                 set_time_limit(5); // 5 seconds timeout
00186 
00187                 try {
00188                     // Ensure proper parameter handling for PHP 8.5.7 compatibility
00189                     $result = call_user_func($function, $param);
00190 
00191                     // Reset the timeout
00192                     set_time_limit($originalTimeout);
00193 
00194                     if ($checkError && $result !== null) {
00195                         // Convert to int before using dechex for PHP 8.5.7 compatibility
00196                         $resultInt = is_numeric($result) ? (int)$result : 0;
00197                         if (dechex($resultInt) != self::WIN32_NO_ERROR) {
00198                             $this->latestError = dechex($resultInt);
00199                         }
00200                     }
00201                 } catch (\Win32ServiceException $e) {
00202                     // Reset the timeout
00203                     set_time_limit($originalTimeout);
00204 
00205                     Log::trace("Win32ServiceException caught: " . $e->getMessage());
00206 
00207                     // Handle "service does not exist" exception
00208                     if (strpos($e->getMessage(), 'service does not exist') !== false) {
00209                         Log::trace("Service does not exist exception handled for: " . $param);
00210                         // Return the appropriate error code for "service does not exist"
00211                         $result = hexdec(self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST);
00212                     } else {
00213                         // For other exceptions, log and return false
00214                         Log::trace("Unhandled Win32ServiceException: " . $e->getMessage());
00215                         $result = false;
00216                     }
00217                 } catch (\Exception $e) {
00218                     // Reset the timeout
00219                     set_time_limit($originalTimeout);
