00223                     $result = false;
00224                 } catch (\Throwable $e) {
00225                     // Reset the timeout
00226                     set_time_limit($originalTimeout);
00227 
00228                     // Catch any other throwable (PHP 7+) to prevent application freeze
00229                     Log::trace("Throwable caught in callWin32Service: " . $e->getMessage());
00230                     $result = false;
00231                 }
00232             } else {
00233                 // Standard handling for other functions
00234                 try {
