00283     public function status($timeout = true): string
00284     {
00285         $this->latestStatus = self::WIN32_SERVICE_NA;
00286         $maxtime            = time() + self::PENDING_TIMEOUT;
00287 
00288         Log::trace("Querying status for service: " . $this->getName() . " (timeout: " . ($timeout ? "enabled" : "disabled") . ")");
00289         if ($timeout) {
00290             Log::trace("Max timeout time set to: " . date('Y-m-d H:i:s', $maxtime));
00291         }
00292 
00293         // Add a safety counter to prevent infinite loops
00294         $loopCount = 0;
00295         $maxLoops = 5; // Maximum number of attempts
00296         $startTime = microtime(true);
00297 
00298         try {
00299             while ( ($this->latestStatus == self::WIN32_SERVICE_NA || $this->isPending( $this->latestStatus )) && $loopCount < $maxLoops ) {
00300                 $loopCount++;
00301                 Log::trace("Calling win32_query_service_status for service: " . $this->getName() . " (attempt " . $loopCount . " of " . $maxLoops . ")");
00302 
00303                 // Add a timeout check before making the call
00304                 if (microtime(true) - $startTime > 10) { // 10 seconds overall timeout
00305                     Log::trace("Overall timeout reached before making service status call");
00306                     break;
00307                 }
00308 
00309                 $this->latestStatus = $this->callWin32Service( 'win32_query_service_status', $this->getName() );
00310 
00311                 if ( is_array( $this->latestStatus ) && isset( $this->latestStatus['CurrentState'] ) ) {
00312                     // Ensure proper type conversion for PHP 8.5.7 compatibility
00313                     $stateInt = is_numeric($this->latestStatus['CurrentState']) ? (int)$this->latestStatus['CurrentState'] : 0;
00314                     $this->latestStatus = dechex( $stateInt );
00315                     Log::trace("Service status returned as array, CurrentState: " . $this->latestStatus);
00316                 }
00317                 elseif ( $this->latestStatus !== null ) {
00318                     // Ensure proper type conversion for PHP 8.5.7 compatibility
00319                     $statusInt = is_numeric($this->latestStatus) ? (int)$this->latestStatus : 0;
00320                     $statusHex = dechex( $statusInt );
00321                     Log::trace("Service status returned as value: " . $statusHex);
00322 
00323                     if ( $statusHex == self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST ) {
00324                         $this->latestStatus = $statusHex;
00325                         Log::trace("Service does not exist, breaking loop");
00326                         break; // Exit the loop immediately if service doesn't exist
00327                     }
00328                 } else {
00329                     Log::trace("Service status query returned null");
00330                     // If we get a null result, assume service does not exist to avoid hanging
00331                     if ($loopCount >= 2) // Only do this after at least one retry
00332                     {
00333                         Log::trace("Multiple null results, assuming service does not exist");
00334                         $this->latestStatus = self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST;
00335                         break;
00336                     }
00337                 }
00338 
00339                 if ( $timeout && $maxtime < time() ) {
00340                     Log::trace("Timeout reached while querying service status");
00341                     break;
00342                 }
00343 
00344                 // Only sleep if we're going to loop again
00345                 if ($loopCount < $maxLoops && ($this->latestStatus == self::WIN32_SERVICE_NA || $this->isPending($this->latestStatus))) {
00346                     Log::trace("Sleeping before next status check attempt");
00347                     usleep(self::SLEEP_TIME);
00348                 }
00349             }
00350         } catch (\Exception $e) {
00351             Log::trace("Exception in status method: " . $e->getMessage());
00352             // If an exception occurs, assume service does not exist
00353             $this->latestStatus = self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST;
00354         } catch (\Throwable $e) {
00355             Log::trace("Throwable in status method: " . $e->getMessage());
00356             // If a throwable occurs, assume service does not exist
00357             $this->latestStatus = self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST;
00358         }
00359 
00360         if ($loopCount >= $maxLoops) {
00361             Log::trace("Maximum query attempts reached for service: " . $this->getName());
00362         }
00363 
00364         $elapsedTime = microtime(true) - $startTime;
00365         Log::trace("Status check completed in " . round($elapsedTime, 2) . " seconds after " . $loopCount . " attempts");
00366 
00367         if ( $this->latestStatus == self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST ) {
00368             $this->latestError  = $this->latestStatus;
00369             $this->latestStatus = self::WIN32_SERVICE_NA;
00370             Log::trace("Service does not exist, setting status to NA");
00371         }
00372 
00373         Log::trace("Final status for service " . $this->getName() . ": " . $this->latestStatus);
00374         return $this->latestStatus;
00375     }
