00382     public function create(): bool
00383     {
00384         global $bearsamppBins;
00385 
00386         Log::trace("Starting Win32Service::create for service: " . $this->getName());
00387 
00388         if ( $this->getName() == BinPostgresql::SERVICE_NAME ) {
00389             Log::trace("PostgreSQL service detected - using specialized installation");
