00399         }
00400 
00401         if ( $this->getNssm() instanceof Nssm ) {
00402             Log::trace("Using NSSM for service installation");
00403 
00404             // Ensure Tools are loaded before building environment paths
00405             global $bearsamppTools;
00406             if (!isset($bearsamppTools)) {
00407                 Log::trace("Tools not loaded, forcing synchronous load");
00408                 Root::loadTools();
00409             }
00410 
00411             global $bearsamppRegistry;
00412             $nssmEnvPath = $bearsamppRegistry->getAppBinsRegKey( false );
00413             Log::trace("NSSM environment path (bins): " . $nssmEnvPath);
00414 
00415             $nssmEnvPath .= Path::getNssmEnvPaths();
00416             Log::trace("NSSM environment path (with additional paths): " . $nssmEnvPath);
00417 
00418             $nssmEnvPath .= '%SystemRoot%/system32;';
00419             $nssmEnvPath .= '%SystemRoot%;';
00420             $nssmEnvPath .= '%SystemRoot%/system32/Wbem;';
00421             $nssmEnvPath .= '%SystemRoot%/system32/WindowsPowerShell/v1.0';
00422             Log::trace("NSSM final environment PATH: " . $nssmEnvPath);
00423 
00424             $this->getNssm()->setEnvironmentExtra( 'PATH=' . $nssmEnvPath );
00425             Log::trace("NSSM service parameters:");
00426             Log::trace("-> Name: " . $this->getNssm()->getName());
00427             Log::trace("-> DisplayName: " . $this->getNssm()->getDisplayName());
00428             Log::trace("-> BinPath: " . $this->getNssm()->getBinPath());
00429             Log::trace("-> Params: " . $this->getNssm()->getParams());
00430             Log::trace("-> Start: " . $this->getNssm()->getStart());
00431             Log::trace("-> Stdout: " . $this->getNssm()->getStdout());
00432             Log::trace("-> Stderr: " . $this->getNssm()->getStderr());
00433 
00434             $result = $this->getNssm()->create();
00435             Log::trace("NSSM service creation " . ($result ? "succeeded" : "failed"));
00436             if (!$result) {
00437                 Log::trace("NSSM error: " . $this->getNssm()->getLatestError());
00438             }
00439             return $result;
00440         }
00441 
00442         Log::trace("Using win32_create_service for service installation");
00443         $serviceParams = array(
00444             'service'       => $this->getName(),
00445             'display'       => $this->getDisplayName(),
00446             'description'   => $this->getDisplayName(),
00447             'path'          => $this->getBinPath(),
00448             'params'        => $this->getParams(),
00449             'start_type'    => $this->getStartType() != null ? $this->getStartType() : self::SERVICE_DEMAND_START,
00450             'error_control' => $this->getErrorControl() != null ? $this->getErrorControl() : self::SERVER_ERROR_NORMAL,
00451         );
00452 
00453         Log::trace("win32_create_service parameters:");
00454         foreach ($serviceParams as $key => $value) {
00455             Log::trace("-> $key: $value");
00456         }
00457 
00458         $result = $this->callWin32Service( 'win32_create_service', $serviceParams, true );
00459         // Ensure proper type conversion for PHP 8.5.7 compatibility
00460         $resultInt = is_numeric($result) ? (int)$result : 0;
00461         $create = $result !== null ? dechex( $resultInt ) : '0';
00462         Log::trace("win32_create_service result code: " . $create);
00463 
00464         // Retry once if the SCM has the service marked for deletion from a recent delete()
00465         if ( $create == self::WIN32_ERROR_SERVICE_MARKED_FOR_DELETE ) {
00466             Log::trace("Service marked for delete, waiting 2s before retry: " . $this->getName());
00467             usleep( 2000000 );
00468             $result   = $this->callWin32Service( 'win32_create_service', $serviceParams, true );
00469             $resultInt = is_numeric($result) ? (int)$result : 0;
00470             $create   = $result !== null ? dechex( $resultInt ) : '0';
00471             Log::trace("win32_create_service retry result code: " . $create);
00472         }
00473 
00474         $this->writeLog( 'Create service: ' . $create . ' (status: ' . $this->status() . ')' );
00475         $this->writeLog( '-> service: ' . $this->getName() );
00476         $this->writeLog( '-> display: ' . $this->getDisplayName() );
00477         $this->writeLog( '-> description: ' . $this->getDisplayName() );
00478         $this->writeLog( '-> path: ' . $this->getBinPath() );
00479         $this->writeLog( '-> params: ' . $this->getParams() );
00480         $this->writeLog( '-> start_type: ' . ($this->getStartType() != null ? $this->getStartType() : self::SERVICE_DEMAND_START) );
00481         $this->writeLog( '-> service: ' . ($this->getErrorControl() != null ? $this->getErrorControl() : self::SERVER_ERROR_NORMAL) );
00482 
00483         if ( $create != self::WIN32_NO_ERROR ) {
00484             Log::trace("Service creation failed with error code: " . $create);
00485             return false;
00486         }
00487         elseif ( !$this->isInstalled() ) {
00488             Log::trace("Service created but not found as installed");
00489             $this->latestError = self::WIN32_NO_ERROR;
00490             return false;
00491         }
00492 
00493         Log::trace("Service created successfully: " . $this->getName());
00494         return true;
00495     }
