00502     public function delete(): bool
00503     {
00504         Log::trace("Starting Win32Service::delete for service: " . $this->getName());
00505         Log::trace("Checking if service is installed: " . $this->getName());
00506 
00507         if ( !$this->isInstalled() ) {
00508             Log::trace("Service is not installed, skipping deletion: " . $this->getName());
00509             return true;
00510         }
00511 
00512         Log::trace("Stopping service before deletion: " . $this->getName());
00513         $this->stop();
00514 
00515         if ( $this->getNssm() instanceof Nssm ) {
00516             $childExe = basename( $this->getNssm()->getBinPath() );
00517             Log::trace("Killing NSSM child process after stop: " . $childExe);
00518             Win32Ps::killBins( [$childExe] );
00519         }
00520 
00521         if ( $this->getName() == BinPostgresql::SERVICE_NAME ) {
00522             Log::trace("PostgreSQL service detected - using specialized uninstallation");
00523             $result = Batch::uninstallPostgresqlService();
00524             Log::trace("PostgreSQL service uninstallation " . ($result ? "succeeded" : "failed"));
00525             return $result;
00526         }
00527 
00528         Log::trace("Calling win32_delete_service for service: " . $this->getName());
00529         $result = $this->callWin32Service( 'win32_delete_service', $this->getName(), true );
00530         // Ensure proper type conversion for PHP 8.5.7 compatibility
00531         $resultInt = is_numeric($result) ? (int)$result : 0;
00532         $delete = $result !== null ? dechex( $resultInt ) : '0';
00533         Log::trace("Delete service result code: " . $delete);
00534         $this->writeLog( 'Delete service ' . $this->getName() . ': ' . $delete . ' (status: ' . $this->status() . ')' );
00535 
00536         if ( $delete != self::WIN32_NO_ERROR && $delete != self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST ) {
00537             return false;
00538         }
00539         elseif ( $this->isInstalled() ) {
00540             $this->latestError = self::WIN32_NO_ERROR;
00541 
00542             return false;
00543         }
00544 
00545         return true;
00546     }
