00569     public function start(): bool
00570     {
00571         global $bearsamppBins;
00572 
00573         Log::info('Attempting to start service: ' . $this->getName());
00574 
00575         if ( $this->getName() == BinMysql::SERVICE_NAME ) {
00576             $bearsamppBins->getMysql()->initData();
00577         }
00578         elseif ( $this->getName() == BinMariadb::SERVICE_NAME ) {
00579             $bearsamppBins->getMariadb()->initData();
00580         }
00581         elseif ( $this->getName() == BinMailpit::SERVICE_NAME ) {
00582             $bearsamppBins->getMailpit()->rebuildConf();
00583         }
00584         elseif ( $this->getName() == BinMemcached::SERVICE_NAME ) {
00585             $bearsamppBins->getMemcached()->rebuildConf();
00586         }
00587         elseif ( $this->getName() == BinPostgresql::SERVICE_NAME ) {
00588             $bearsamppBins->getPostgresql()->rebuildConf();
00589             $bearsamppBins->getPostgresql()->initData();
00590         }
00591         elseif ( $this->getName() == BinXlight::SERVICE_NAME ) {
00592             $bearsamppBins->getXlight()->rebuildConf();
00593         }
00594 
00595 
00596         $result = $this->callWin32Service( 'win32_start_service', $this->getName(), true );
00597         // Ensure proper type conversion for PHP 8.5.7 compatibility
00598         $resultInt = is_numeric($result) ? (int)$result : 0;
00599         $start = $result !== null ? dechex( $resultInt ) : '0';
00600         Log::debug( 'Start service ' . $this->getName() . ': ' . $start . ' (status: ' . $this->status() . ')' );
00601 
00602         if ( $start != self::WIN32_NO_ERROR && $start != self::WIN32_ERROR_SERVICE_ALREADY_RUNNING ) {
00603 
00604             // Write error to log
00605             Log::error('Failed to start service: ' . $this->getName() . ' with error code: ' . $start);
00606 
00607             if ( $this->getName() == BinApache::SERVICE_NAME ) {
00608                 $cmdOutput = $bearsamppBins->getApache()->getCmdLineOutput( BinApache::CMD_SYNTAX_CHECK );
00609                 if ( !$cmdOutput['syntaxOk'] ) {
00610                     file_put_contents(
00611                         $bearsamppBins->getApache()->getErrorLog(),
00612                         '[' . date( 'Y-m-d H:i:s', time() ) . '] [error] ' . $cmdOutput['content'] . PHP_EOL,
00613                         FILE_APPEND
00614                     );
00615                 }
00616             }
00617             elseif ( $this->getName() == BinMysql::SERVICE_NAME ) {
00618                 $cmdOutput = $bearsamppBins->getMysql()->getCmdLineOutput( BinMysql::CMD_SYNTAX_CHECK );
00619                 if ( !$cmdOutput['syntaxOk'] ) {
00620                     file_put_contents(
00621                         $bearsamppBins->getMysql()->getErrorLog(),
00622                         '[' . date( 'Y-m-d H:i:s', time() ) . '] [error] ' . $cmdOutput['content'] . PHP_EOL,
00623                         FILE_APPEND
00624                     );
00625                 }
00626             }
00627             elseif ( $this->getName() == BinMariadb::SERVICE_NAME ) {
00628                 $cmdOutput = $bearsamppBins->getMariadb()->getCmdLineOutput( BinMariadb::CMD_SYNTAX_CHECK );
00629                 if ( !$cmdOutput['syntaxOk'] ) {
00630                     file_put_contents(
00631                         $bearsamppBins->getMariadb()->getErrorLog(),
00632                         '[' . date( 'Y-m-d H:i:s', time() ) . '] [error] ' . $cmdOutput['content'] . PHP_EOL,
00633                         FILE_APPEND
00634                     );
00635                 }
00636             }
00637 
00638             return false;
00639         }
00640 
00641         // Wait for the service to actually start before checking if it's running
00642         // We use a timeout to avoid hanging if the service fails to start properly
00643         $maxtime = time() + self::PENDING_TIMEOUT;
00644         while ($this->isPending($this->status(false)) && time() < $maxtime) {
00645             usleep(self::SLEEP_TIME);
00646         }
00647 
00648         if ( !$this->isRunning() ) {
00649             $this->latestError = self::WIN32_NO_ERROR;
00650             Log::error('Service ' . $this->getName() . ' is not running after start attempt (status: ' . $this->status() . ').');
00651             $this->latestError = null;
00652             return false;
00653         }
00654 
00655         Log::info('Service ' . $this->getName() . ' started successfully.');
00656         return true;
00657     }
