00664     public function stop(): bool
00665     {
00666         Log::trace("Starting Win32Service::stop for service: " . $this->getName());
00667 
00668         Log::trace("Calling win32_stop_service for service: " . $this->getName());
00669         $result = $this->callWin32Service( 'win32_stop_service', $this->getName(), true );
00670 
00671         // Ensure proper type conversion for PHP 8.5.7 compatibility
00672         $resultInt = is_numeric($result) ? (int)$result : 0;
00673         $stop = $result !== null ? dechex( $resultInt ) : '0';
00674         Log::trace("Stop service result code: " . $stop);
00675 
00676         Log::trace("Checking current status after stop attempt");
00677         $currentStatus = $this->status();
00678         Log::trace("Current status: " . $currentStatus);
00679 
00680         $this->writeLog( 'Stop service ' . $this->getName() . ': ' . $stop . ' (status: ' . $currentStatus . ')' );
00681 
00682         if ( $stop != self::WIN32_NO_ERROR ) {
00683             return false;
00684         }
00685 
00686         // Wait for the service to actually stop before checking if it's stopped
00687         $maxtime = time() + self::PENDING_TIMEOUT;
00688         while ($this->isPending($this->status(false)) && time() < $maxtime) {
00689             usleep(self::SLEEP_TIME);
00690         }
00691 
00692         if ( !$this->isStopped() ) {
00693             $this->latestError = self::WIN32_NO_ERROR;
00694             Log::error('Service ' . $this->getName() . ' is still running after stop attempt (status: ' . $this->status() . ').');
00695             $this->latestError = null;
00696             return false;
00697         }
00698 
00699         return true;
00700     }
