00722     public function fastServiceCheck()
00723     {
00724         Log::trace("Starting fastServiceCheck for service: " . $this->getName());
00725 
00726         $startTime = microtime(true);
00727 
00728         // Use sc.exe to query service - this is very fast and reliable
00729         // Execute with hidden window to prevent command prompt flash
00730         Log::trace("Executing: sc query " . $this->getName());
00731 
00732         $output = CommandRunner::execCombined('sc', ['query', $this->getName()]);
00733         $duration = round(microtime(true) - $startTime, 3);
00734 
00735         Log::trace("sc.exe query completed in " . $duration . "s");
00736 
00737         if ($output === null || $output === false) {
00738             Log::trace("sc.exe returned null/false, service likely doesn't exist");
00739             return false;
00740         }
00741 
00742         // Check if service doesn't exist
00743         if (stripos($output, 'does not exist') !== false ||
00744             stripos($output, 'FAILED') !== false ||
00745             stripos($output, '1060') !== false) {  // Error code 1060 = service doesn't exist
00746             Log::trace("Service doesn't exist: " . $this->getName());
00747             return false;
00748         }
00749 
00750         // Service exists - parse basic info
00751         $serviceInfo = [];
00752 
00753         // Extract service name
00754         if (preg_match('/SERVICE_NAME:\s*(.+)/i', $output, $matches)) {
00755             $serviceInfo[self::VBS_NAME] = trim($matches[1]);
00756         }
00757 
00758         // Extract display name
00759         if (preg_match('/DISPLAY_NAME:\s*(.+)/i', $output, $matches)) {
00760             $serviceInfo[self::VBS_DISPLAY_NAME] = trim($matches[1]);
00761         }
00762 
00763         // Extract state
00764         if (preg_match('/STATE\s*:\s*\d+\s+(\w+)/i', $output, $matches)) {
00765             $state = trim($matches[1]);
00766             $serviceInfo[self::SERVICE_STATE] = $state;
00767             Log::trace("Service state: " . $state);
00768         }
00769 
00770         // If we have basic info, service exists - get full details if needed
00771         if (!empty($serviceInfo)) {
00772             Log::trace("Service exists, getting full details");
00773 
00774             // Use sc qc to get configuration details (including path)
00775             $configOutput = CommandRunner::execCombined('sc', ['qc', $this->getName()]);
00776 
00777             if ($configOutput !== null && $configOutput !== false && preg_match('/BINARY_PATH_NAME\s*:\s*(.+)/i', $configOutput, $matches)) {
00778                 $serviceInfo[self::VBS_PATH_NAME] = trim($matches[1]);
00779                 Log::trace("Service path: " . $serviceInfo[self::VBS_PATH_NAME]);
00780             }
00781 
00782             // Get description if available
00783             if ($configOutput !== null && $configOutput !== false && preg_match('/DISPLAY_NAME\s*:\s*(.+)/i', $configOutput, $matches)) {
00784                 $serviceInfo[self::VBS_DESCRIPTION] = trim($matches[1]);
00785             }
00786 
00787             Log::trace("Fast service check successful for: " . $this->getName());
00788             return $serviceInfo;
00789         }
00790 
00791         Log::trace("Could not parse service info from sc.exe output");
00792         return false;
00793     }
