00801     public function infos()
00802     {
00803         Log::trace("Starting Win32Service::infos for service: " . $this->getName());
00804 
00805         try {
00806             // Set a timeout for the entire operation
00807             $startTime = microtime(true);
00808             $timeout = 10; // 10 seconds timeout for the entire operation
00809 
00810             if ($this->getNssm() instanceof Nssm) {
00811                 Log::trace("Using NSSM to get service info");
00812                 $result = $this->getNssm()->infos();
00813                 Log::trace("NSSM info retrieval completed in " . round(microtime(true) - $startTime, 2) . " seconds");
00814                 return $result;
00815             }
00816 
00817             // Performance optimization: Try fast sc.exe check first
00818             Log::trace("Attempting fast service check using sc.exe");
00819             $fastResult = $this->fastServiceCheck();
00820 
00821             if ($fastResult !== false) {
00822                 $duration = round(microtime(true) - $startTime, 3);
00823                 Log::trace("Fast service check succeeded in " . $duration . "s (saved 5-10s)");
00824                 Log::debug("Performance: Fast service check used for " . $this->getName() . ", saved 5-10 seconds");
00825                 return $fastResult;
00826             }
00827 
00828             // Fast check returned false - service doesn't exist
00829             if ($fastResult === false) {
00830                 $duration = round(microtime(true) - $startTime, 3);
00831                 Log::trace("Fast service check determined service doesn't exist in " . $duration . "s");
00832                 return false;
00833             }
00834 
00835             // Fallback to VBS (should rarely be needed now)
00836             Log::trace("Falling back to VBS for service info");
00837 
00838             // Use set_time_limit to prevent PHP script timeout
00839             $originalTimeout = ini_get('max_execution_time');
00840             set_time_limit(15); // 15 seconds timeout
00841 
00842             // Create a separate process to get service info with a timeout
00843             $result = Win32Native::getServiceInfo($this->getName());
00844 
00845             // Reset the timeout
00846             set_time_limit($originalTimeout);
00847 
00848             // Check if we've exceeded our timeout
00849             if (microtime(true) - $startTime > $timeout) {
00850                 Log::trace("Timeout exceeded in infos() method, returning false");
00851                 return false;
00852             }
00853 
00854             Log::trace("VBS info retrieval completed in " . round(microtime(true) - $startTime, 2) . " seconds");
00855             return $result;
00856         } catch (\Exception $e) {
00857             Log::trace("Exception in infos() method: " . $e->getMessage() . ", returning false");
00858             return false;
00859         } catch (\Throwable $e) {
00860             Log::trace("Throwable in infos() method: " . $e->getMessage() . ", returning false");
00861             return false;
00862         }
00863     }
