00870     public function isInstalled(): bool
00871     {
00872         Log::trace("Checking if service is installed: " . $this->getName());
00873 
00874         try {
00875             // Set a timeout for the entire operation
00876             $startTime = microtime(true);
00877             $timeout = 15; // 15 seconds timeout for the entire operation
00878 
00879             // Call status() with a try-catch to ensure we don't get stuck
00880             $status = $this->status();
00881 
00882             // Check if we've exceeded our timeout
00883             if (microtime(true) - $startTime > $timeout) {
00884                 Log::trace("Timeout exceeded in isInstalled() method, assuming service is not installed");
00885                 $this->writeLog('isInstalled ' . $this->getName() . ': NO (timeout exceeded)');
00886                 return false;
00887             }
00888 
00889             $isInstalled = $status != self::WIN32_SERVICE_NA;
00890 
00891             Log::trace("Service " . $this->getName() . " installation status: " . ($isInstalled ? "YES" : "NO") . " (status code: " . $status . ")");
00892             $this->writeLog('isInstalled ' . $this->getName() . ': ' . ($isInstalled ? 'YES' : 'NO') . ' (status: ' . $status . ')');
00893 
00894             return $isInstalled;
00895         } catch (\Exception $e) {
00896             Log::trace("Exception in isInstalled() method: " . $e->getMessage() . ", assuming service is not installed");
00897             $this->writeLog('isInstalled ' . $this->getName() . ': NO (exception: ' . $e->getMessage() . ')');
00898             return false;
00899         } catch (\Throwable $e) {
00900             Log::trace("Throwable in isInstalled() method: " . $e->getMessage() . ", assuming service is not installed");
00901             $this->writeLog('isInstalled ' . $this->getName() . ': NO (throwable: ' . $e->getMessage() . ')');
00902             return false;
00903         }
00904     }
