00967     public function isPending($status): bool
00968     {
00969         $isPending = $status == self::WIN32_SERVICE_START_PENDING || $status == self::WIN32_SERVICE_STOP_PENDING
00970             || $status == self::WIN32_SERVICE_CONTINUE_PENDING || $status == self::WIN32_SERVICE_PAUSE_PENDING;
00971 
00972         Log::trace("Checking if status is pending: " . $status . " - Result: " . ($isPending ? "YES" : "NO"));
00973 
00974         if ($isPending) {
00975             if ($status == self::WIN32_SERVICE_START_PENDING) {
00976                 Log::trace("Service is in START_PENDING state");
00977             } else if ($status == self::WIN32_SERVICE_STOP_PENDING) {
00978                 Log::trace("Service is in STOP_PENDING state");
00979             } else if ($status == self::WIN32_SERVICE_CONTINUE_PENDING) {
00980                 Log::trace("Service is in CONTINUE_PENDING state");
00981             } else if ($status == self::WIN32_SERVICE_PAUSE_PENDING) {
00982                 Log::trace("Service is in PAUSE_PENDING state");
00983             }
00984         }
00985 
00986         return $isPending;
00987     }
