00996     private function getWin32ServiceStatusDesc($status): ?string
00997     {
00998         switch ( $status ) {
00999             case self::WIN32_SERVICE_CONTINUE_PENDING:
01000                 return 'The service continue is pending.';
01001 
01002             case self::WIN32_SERVICE_PAUSE_PENDING:
01003                 return 'The service pause is pending.';
01004 
01005             case self::WIN32_SERVICE_PAUSED:
01006                 return 'The service is paused.';
01007 
01008             case self::WIN32_SERVICE_RUNNING:
01009                 return 'The service is running.';
01010 
01011             case self::WIN32_SERVICE_START_PENDING:
01012                 return 'The service is starting.';
01013 
01014             case self::WIN32_SERVICE_STOP_PENDING:
01015                 return 'The service is stopping.';
01016 
01017             case self::WIN32_SERVICE_STOPPED:
01018                 return 'The service is not running.';
01019 
01020             case self::WIN32_SERVICE_NA:
01021                 return 'Cannot retrieve service status.';
01022 
01023             default:
01024                 return null;
01025         }
01026     }
