01245     public function waitForServiceDeletion($maxWaitTime = 30): bool
01246     {
01247         $startTime = time();
01248         $maxTime = $startTime + $maxWaitTime;
01249         $checkCount = 0;
01250 
01251         Log::trace("Waiting for service deletion: " . $this->getName() . " (max wait: " . $maxWaitTime . "s)");
01252 
01253         while (time() < $maxTime) {
01254             $checkCount++;
01255             $status = $this->status(false);
01256             Log::trace("Service deletion check #" . $checkCount . " - Status: " . $status . " at " . date('Y-m-d H:i:s'));
01257 
01258             // Service doesn't exist or is definitely not there
01259             if ($status == self::WIN32_SERVICE_NA ||
01260                 $status == self::WIN32_ERROR_SERVICE_DOES_NOT_EXIST) {
01261                 $elapsedTime = time() - $startTime;
01262                 Log::trace("Service deletion confirmed after " . $elapsedTime . " seconds");
01263                 return true;
01264             }
01265 
01266             // Wait a bit before checking again
01267             usleep(500000); // 0.5 seconds
01268         }
01269 
01270         $totalWaitTime = time() - $startTime;
01271         Log::trace("Service deletion timeout after " . $totalWaitTime . " seconds - service still exists: " . $this->getName());
01272         return false;
01273     }
01274 
01281     public function ensureReset(): bool
01282     {
01283         Log::trace("Starting ensureReset for service: " . $this->getName());
01284 
01285         // First, make sure service is stopped
01286         if ($this->isRunning()) {
01287             Log::trace("Service is still running, stopping it first");
01288             if (!$this->stop()) {
01289                 Log::trace("Failed to stop service during ensureReset");
01290                 return false;
01291             }
01292             usleep(1000000); // 1 second wait after stop
01293         }
01294 
01295         // Delete the service
01296         Log::trace("Deleting service");
01297         if (!$this->delete()) {
01298             Log::trace("Service deletion failed, but continuing with wait");
01299         }
01300 
01301         // Wait for the service to be completely removed
01302         if (!$this->waitForServiceDeletion(30)) {
01303             Log::trace("Service deletion did not complete within timeout, but continuing");
01304             // Even if we timeout, give it a moment and try to create anyway
01305             usleep(2000000); // 2 seconds
01306         }
01307 
01308         Log::trace("ensureReset completed for service: " . $this->getName());
01309         return true;
01310     }
01311 }
